-- =============================================================================
-- More areas for Hyderabad, Gurugram, Noida, Mumbai and Delhi (captain 2026-11-28:
-- "when they are typing area you can suggest the area name or pin code autofill
-- if they select that area"). V11 seeded only 10-12 well-known localities in each
-- of these live cities, so many users typing their area found no suggestion and
-- no PIN autofill. These are further main residential localities, ACTIVE
-- reference rows (not demo data, so every profile gets them): 109 areas, ids
-- 401-509. BLR and PNQ are already covered by V18.
--
-- PIN source: India Post "All India Pincode Directory" (post office list with PIN
-- codes, Department of Posts, Open Government Data Platform India), published
-- under the Government Open Data License - India (GODL):
--   https://data.gov.in/resource/all-india-pincode-directory-till-last-month
--   file: https://www.data.gov.in/sites/default/files/all_india_PO_list_without_APS_offices_ver2_lat_long.csv
--   (sha256 6cb2edb44b568077b9d8a2962cffba05dafc1799e536c34fe9a30c75484612c1, read 2026-11-28,
--   the same file as V18)
-- Every PIN below is the pincode of the India Post office(s) named in the comment
-- above its area, inside the city's own PIN prefixes (V3, V8); none is typed by hand.
-- The data stays in this migration: the app never calls India Post or any other
-- outside service while a user types.
--
-- Duplicates are skipped exactly as in V18: a locality is skipped when its city
-- already has an ACTIVE or demo area of that name, an area named like one of its
-- aliases, or an area that lists this name among its aliases. A PENDING or HIDDEN
-- row with the exact name is made ACTIVE in place (same id and created_by), with
-- the reference aliases and PIN codes; its PIN codes that are not in the India
-- Post list and that no home on it uses are removed. ACTIVE rows are never touched.
-- Ids are fixed small numbers, far below the time-ordered ids the app makes (D-12).
-- Same portable subset as V1 (D-10).
-- =============================================================================

-- HYD
-- Secunderabad: India Post Secunderabad H.O 500003
INSERT INTO areas (id, public_id, city_code, name, name_key, aliases, status, created_by, is_demo, created_at, updated_at)
SELECT 401, '01a205b3-d000-7b19-8fa8-2c5eb89d1a88', code, 'Secunderabad', 'secunderabad', NULL, 'ACTIVE', NULL, FALSE, '2026-11-28 00:00:00.000', '2026-11-28 00:00:00.000' FROM cities
WHERE code = 'HYD' AND NOT EXISTS (SELECT 1 FROM areas WHERE city_code = 'HYD' AND (status = 'ACTIVE' OR is_demo = TRUE) AND (name_key = 'secunderabad' OR LOWER(aliases) LIKE '%secunderabad%')) AND NOT EXISTS (SELECT 1 FROM areas WHERE city_code = 'HYD' AND name_key = 'secunderabad');
INSERT INTO area_pincodes (area_id, pincode, created_at, updated_at) SELECT id, '500003', '2026-11-28 00:00:00.000', '2026-11-28 00:00:00.000' FROM areas WHERE city_code = 'HYD' AND name_key = 'secunderabad' AND (id = 401 OR (status <> 'ACTIVE' AND is_demo = FALSE AND NOT EXISTS (SELECT 1 FROM areas m WHERE m.city_code = 'HYD' AND (m.status = 'ACTIVE' OR m.is_demo = TRUE) AND (m.name_key = 'secunderabad' OR LOWER(m.aliases) LIKE '%secunderabad%')))) AND NOT EXISTS (SELECT 1 FROM area_pincodes p WHERE p.area_id = areas.id AND p.pincode = '500003');
DELETE FROM area_pincodes WHERE NOT EXISTS (SELECT 1 FROM properties h WHERE h.area_id = area_pincodes.area_id AND h.pincode = area_pincodes.pincode) AND pincode NOT IN ('500003') AND area_id IN (SELECT id FROM areas WHERE city_code = 'HYD' AND name_key = 'secunderabad' AND status <> 'ACTIVE' AND is_demo = FALSE AND NOT EXISTS (SELECT 1 FROM areas m WHERE m.city_code = 'HYD' AND (m.status = 'ACTIVE' OR m.is_demo = TRUE) AND (m.name_key = 'secunderabad' OR LOWER(m.aliases) LIKE '%secunderabad%')));
UPDATE areas SET name = 'Secunderabad', status = 'ACTIVE', updated_at = '2026-11-28 00:00:00.000' WHERE city_code = 'HYD' AND name_key = 'secunderabad' AND status <> 'ACTIVE' AND is_demo = FALSE AND NOT EXISTS (SELECT 1 FROM (SELECT city_code, name_key, aliases, status, is_demo FROM areas) m WHERE m.city_code = 'HYD' AND (m.status = 'ACTIVE' OR m.is_demo = TRUE) AND (m.name_key = 'secunderabad' OR LOWER(m.aliases) LIKE '%secunderabad%'));
